const baseStrategySchema=z.object({category:z.enum(businessCategories),customer:z.string(),situation:z.string(),market:z.string(),mechanism:z.string(),action:z.string(),destination:z.string(),imageStyle:z.string(),visualPriority:z.enum(['product','service','editorial']),angles:z.array(z.object({idea:z.string(),usefulInsight:z.string(),hooks:z.array(z.string()).length(1),evidence:z.array(z.string())})).length(3),chosenAngles:z.array(z.string()).length(2),note:z.string()});
const designSchema=z.object({layout:z.enum(['essay','poster','split','photo','list','note','diagram','product']),surface:z.enum(['paper','primary','ink','accent']),align:z.enum(['left','center']),imagePosition:z.enum(['top','bottom','right']),emphasis:z.string().max(100),takeaway:z.string().max(200)});
const baseFrameSchema=z.object({heading:z.string().trim().min(1).max(160),body:z.string().max(600),design:designSchema,composition:z.enum(['editorial','checklist','comparison','process','spotlight','image','closing']),eyebrow:z.string().max(48),assetKey:z.string(),items:z.array(z.object({label:z.string().max(100),detail:z.string().max(240)})).max(5)});
const productFrameSchema=baseFrameSchema.extend({heading:z.string().trim().min(1).max(36),body:z.string().max(24),eyebrow:z.literal(''),assetKey:z.string().min(1),items:z.array(z.object({label:z.string(),detail:z.string()})).length(0),design:designSchema.extend({layout:z.literal('product'),takeaway:z.string().max(28)})});
const editorialFrameSchema=baseFrameSchema.extend({design:designSchema.extend({layout:z.enum(['essay','poster','split','photo','list','note','diagram'])})});
